-- Запись журнала обновлений (ADR 0077): выпуск 32 — правки бланков путевых листов.
--
-- Схему миграция не трогает — она только заводит запись выпуска, как 0102, 0109, 0113, 0116, 0125,
-- 0126, 0128, 0134, 0135, 0140, 0158, 0159, 0160 и 0163 (ADR 0077 §4).
--
-- Хвост версии — по последнему решению блока (§2): работа целиком описана ADR 0127, и `0.1.32.0127`
-- монотонно продолжает `0.1.31.0125`. Подверсии («0.1.31.1») здесь не нужно: у блока своё решение
-- есть, а подверсию заводят выпуску, который своего ADR не имеет.
--
-- `released_on` отвечает пользователю на вопрос «с какого числа это работает» и стоит по дню, когда
-- работа доехала до main (§3).
--
-- Схему этого же выпуска меняет соседняя миграция 0164 (`waybill_customer` — реквизиты заказчика).
-- Разметка бланков схемы не касается вовсе: она живёт в файлах шаблонов и прогоняется скриптом.
--
-- Пункты писаны от лица того, кто держит лист в руках: что изменилось на бумаге и в окне. Отдельным
-- пунктом сказано то, о чём спросят первым, — бумагу правки не перевыписывают, и лист, выданный до
-- выката, печатается таким, каким выдан.

INSERT INTO app_releases (seq, version, released_on, title, adrs, items) VALUES (
  39, '0.1.32.0127', '2026-08-20', 'Путевые листы: дата по-русски, заказчик в графе заказчика и объект один раз в шапке', '{127}',
  '[
    {"kind":"fix","text":"Дата на путевом листе печатается днём, месяцем и годом: «23.08.2026» вместо «2026-08-23». Так же печатается и дата выдачи водительского удостоверения. Листы, выданные раньше, выходят из принтера с прежней записью — повторная печать даёт ровно тот документ, который выдан на руки"},
    {"kind":"fix","text":"В графе «В чьё распоряжение (наименование и адрес заказчика)» у 4-П и в графе «Заказчик» у ЭСМ-2 стоит заказчик — генподрядчик и адрес его офиса. Прежде туда шёл объект: графа отвечала «куда поехали» на вопрос «в чьё распоряжение поступила машина», и заказчик по такой бумаге не определялся вовсе"},
    {"kind":"improvement","text":"В недельном листе ЭСМ-2 наименование и адрес объекта печатаются один раз — в шапке графы работ на лицевой стороне и на обороте, — а не повторяются в каждом из семи дней. В строках дней остались числа месяца, которыми лист и ведут"},
    {"kind":"improvement","text":"Номер и дата недельного листа встали на одну линию с заголовком бланка и его кеглем: прежде они стояли строкой выше и ниже заголовка и читались как чужие"},
    {"kind":"fix","text":"С бланков убраны блоки, которые портал не заполняет: «Количество отработанных часов» в 4-П — вместе с рамкой поля и линиями подписи, «коды объектов» в ЭСМ-2 и «Водительское удостоверение проверил» в форме № 3. Блок «Водитель по состоянию здоровья к управлению допущен, алкотест пройден» поднят на освободившееся место"},
    {"kind":"feature","text":"Над графами «(расшифровка подписи)» водителя — в 4-П и в форме № 3 — печатается его имя: «Дегтярь И.В.». Фамилией с инициалами расшифровку и пишут от руки — полное ФИО в узкую графу не встаёт, — а в шапке листа, где бланк просит фамилию, имя и отчество, имя остаётся полным. Графы механика заполняются от руки, как и прежде"},
    {"kind":"improvement","text":"Вид сообщения выбирается списком — городское, пригородное, междугороднее — в назначении техники, правке маршрута и коррекции рейса; у нового рейса стоит «пригородное». Пустым поле не сохранить, а значение старого рейса, написанное по-своему, остаётся на месте: правка дня или водителя не унесёт графу, которая на выданном листе уже напечатана"},
    {"kind":"improvement","text":"В графе «Заказчик» недельного листа больше нет телефона ответственного за встречу машины — там телефон заказчика. Сам контакт никуда не делся: он в заявке и в кабинете водителя, где его и смотрят перед выездом"},
    {"kind":"fix","text":"Бумагу правки не перевыписывают: ни один выданный лист не аннулирован и ни один номер не израсходован. Повторная печать выданного листа идёт новым бланком — убранных блоков в нём уже нет, имя водителя в расшифровках встанет, — а дата, графа заказчика и объект печатаются такими, какими были выданы"}
  ]'::jsonb
);
